def dispatch(name, params, call_params, conc_first, hyps_pass):
    """bd_<name>(d, ...): d's state an instruction state, not the first: the
    class's lemma bd_<name>c"""
    lines = []
    lines.append('def bd_%s(+d: D.LzoDec, %s, +hi: {bd_ins(bd_st(d)) == True{} : Bool}, +hg: {bd_good(bd_st(d)) == True{} : Bool}, hc: bd_cinv(d), %s) -> {D.dec.out(D.dec.end(D.dec.go(%s, d))) == %s : %s}:' % (name, params, hyps_pass[0], conc_first, FAIL, RES))
    lines.append('  match d:')
    lines.append('    case D.LzoDec{st, acc, win, room}:')
    lines.append('      match st:')
    for ctor, fields in CTORS:
        p = pat(ctor, fields)
        lines.append('        case %s:' % p)
        g = '{D.dec.out(D.dec.end(D.dec.go(%s, D.LzoDec{%s, acc, win, room}))) == %s : %s}' % (conc_first, p, FAIL, RES)
        if ctor == 'D.LzoIns':
            lines.append('          bd_%sc(c, acc, win, room, %s, hg, hc, %s)' % (name, call_params, hyps_pass[1]))
        elif ctor == 'D.LzoLit':
            lines.append('          match n:')
            lines.append('            case 0n:')
            lines.append('              bd_%sc(c, acc, win, room, %s, hg, hc, %s)' % (name, call_params, hyps_pass[1]))
            lines.append('            case 1n+p:')
            lines.append('              absurd({D.dec.out(D.dec.end(D.dec.go(%s, D.LzoDec{D.LzoLit{1n+p, c}, acc, win, room}))) == %s : %s}, false_not_true(hi))' % (conc_first, FAIL, RES))
        else:
            lines.append('          absurd(%s, false_not_true(hi))' % g)
    lines.append('')
    return '\n'.join(lines)


