# M4: near (H = 0) and far (H = 1)
def m4_consts(near):
    """the terms of M4's distance, H = 0 (near) or 1"""
    kb, mb = ('14n', '18n') if near else ('15n', '17n')
    WK = W14 if near else W15
    c = {}
    c['kb'], c['mb'] = kb, mb
    c['K'] = 'U32{PD.ld.cat(%s, %s, PD.ld.ones(%s), Word.zero(%s))}' % (kb, mb, kb, mb)
    c['KLIT'] = '16383' if near else '32767'
    c['XH'] = 'PD.ld.cat(1n, %s, PD.ld.ones(1n), Word.zero(%s))' % (('17n', '17n') if near else ('16n', '16n'))
    c['C'] = 'U32{PD.ld.cat(%s, %s, %s, %s)}' % (kb, mb, WK, c['XH'])
    c['DV'] = 'U32.to_nat(U32{PD.ld.cat(%s, %s, %s, Word.zero(%s))})' % (kb, mb, WK, mb)
    c['Y'] = 'U.U32Nat.dbl(%s, Word.to_nat(%s, %s))' % (kb, mb, c['XH'])
    c['KV'] = 'Word.to_nat(%s, PD.ld.ones(%s))' % (kb, kb)
    c['POW'] = 'U.U32Nat.dbl(%s, 1n)' % kb
    c['ek'] = 'PD.ld.uzext14(PD.ld.ones(14n))' if near else 'PD.ld.uzext15(PD.ld.ones(15n))'
    c['ed'] = ('PD.ld.d14_w(%s)' if near else 'PD.ld.d14_w15(%s)') % BA
    c['ec'] = ('PD.ld.ec_gen(%s, %s)' if near else 'PD.ld.ec_gen15(%s, %s)') % (WK, c['XH'])
    c['OK'] = 'U32.to_nat(U32.add(%s, %s))' % (c['K'], D14E)
    c['far'] = 'False{}' if near else 'True{}'
    c['KD'] = 'D.LzoM4{%s}' % c['far']
    return c


def m4_hyps(near, len_term):
    """hz (H = 0) and the bound: (declarations, arguments). The output's
    length is a variable ln, equal to len_term: the bound holds 2^14 (2^15),
    which no conversion may expand"""
    c = m4_consts(near)
    hz = ('+hz: {Nat.is_lt(0n, %s) == True{} : Bool}, ' % DLAW) if near else ''
    return ('%s+ln: Nat, +hn: {ln == %s : Nat}, +hd: {Nat.is_lt(ln, Nat.add(%s, %s)) == True{} : Bool}' % (hz, len_term, c['DV'], c['POW']),
            '%sln, hn, hd' % ('hz, ' if near else ''))


