# Length bytes: L = 0 (x = 32 for M3, 16 and 24 for M4), then z zero bytes,
# each adding 255 to the length, then a byte v other than 0, then lo and hi
w('''# Length bytes: an instruction with L = 0 starts a length (bd_ins_x*); each
# zero byte adds 255 to it (bd_zrun) and a byte v other than 0 ends it
# (bd_zend), in the Dist state of the match (bd_x*c)
def bd_zn(+z: Nat, +n: Nat) -> Nat:
  match z:
    case 0n:
      n
    case 1n+p:
      bd_zn(p, Nat.add(255n, n))

def bd_zrun(+z: Nat, +n: Nat, +k: D.LzoFar, +acc: List<&2, U32>, +win: W.LzoWin, +room: Nat) -> {D.dec.go(B.zeros(z), D.LzoDec{D.LzoMatExt{n, k}, acc, win, room}) == D.LzoDec{D.LzoMatExt{bd_zn(z, n), k}, acc, win, room} : D.LzoDec}:
  match z:
    case 0n:
      {==}
    case 1n+p:
      bd_zrun(p, Nat.add(255n, n), k, acc, win, room)

def bd_zend(+n: Nat, +k: D.LzoFar, +v: U32, +acc: List<&2, U32>, +win: W.LzoWin, +room: Nat, +hv: {U32.is_eq(v, 0) == False{} : Bool}) -> {D.dec.step(D.LzoDec{D.LzoMatExt{n, k}, acc, win, room}, v) == D.LzoDec{D.LzoDist{Nat.add(U32.to_nat(v), n), k}, acc, win, room} : D.LzoDec}:
  %Equal.sym(Bool, U32.is_eq(v, 0), False{}, hv) : {D.dec.apply(D.dec.matext(D.dec.ext.pick(_, v), n, k), acc, win, room) == D.LzoDec{D.LzoDist{Nat.add(U32.to_nat(v), n), k}, acc, win, room} : D.LzoDec}
  {==}
''')

